#!/bin/bash
# iTransformer on Exchange: input 96, horizons 96 192 336 720; settings of the official scripts, protocol of the official loaders.
# Generated by scripts/multivariate_forecasting/make_scripts.py: change the profile and generate again.
#   bash scripts/multivariate_forecasting/Exchange/iTransformer.sh                                   seeds 2021 2022 2023
#   SEEDS="2021" EXTRA_ARGS="--no_use_gpu --num_workers 0" bash scripts/multivariate_forecasting/Exchange/iTransformer.sh   one seed on the CPU
# Results: output/long_term_forecast/Exchange.tsv (one row per run); checkpoints: temp/checkpoints/Exchange/.
export CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-0}
