root="$(python -m src.utils.paths root exchange_rate.csv)/"
seeds=(${SEEDS:-2021 2022 2023})

# horizon 96: scripts/benchmark/official/iTransformer/Exchange/iTransformer.sh
for seed in "${seeds[@]}"; do
  python -u scripts/run.py \
    --is_training 1 \
    --model iTransformer \
    --des Exchange_96_iTransformer \
    --seed "$seed" \
    --root_path "$root" \
    --data_path exchange_rate.csv \
    --data custom \
    --model_id Exchange_96_96 \
    --features M \
    --seq_len 96 \
    --label_len 48 \
    --pred_len 96 \
    --enc_in 8 \
    --dec_in 8 \
    --c_out 8 \
    --freq h \
    --drop_last \
    --test_batch_size 1 \
    --e_layers 2 \
    --d_model 128 \
    --d_ff 128 \
    $EXTRA_ARGS
done

